"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000000, '9c8b7259-de7f-5a31-8f39-515f70e2b999', 0, '2026-11-23 06:25:54', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#1-sales-order', 'Y', 'Sales Order + 1 · Sales Order + Step 7 · Enter the order header + Step 9 · Complete the order', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000000, 1000000, '9c9ac7c9-c759-5df2-aa0b-3b77c4aa9a1f', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Sales Order</strong></p><p><b>Before you start.</b> These must exist first: Target Document Type (<a href=\"#\" data-help-win=\"135\">Document Type</a>), <a href=\"#\" data-help-win=\"123\">Business Partner</a>, Partner Location (<a href=\"#\" data-help-win=\"123\">Business Partner</a>), Warehouse (<a href=\"#\" data-help-win=\"139\">Warehouse and Locators</a>), <a href=\"#\" data-help-win=\"146\">Price List</a>, Sales Representative (<a href=\"#\" data-help-win=\"108\">User</a>), <a href=\"#\" data-help-win=\"141\">Payment Term</a>.</p><p><b>Do it.</b> Fill <b>Order</b>, then <b>Order Line</b>, <b>Order Tax</b>, <b>Payment Schedule</b>, <b>POS Payment</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>On Credit Order, Warehouse Order, POS Order (Prepay Order if <i>Generate Shipment</i>): also creates and completes the shipment ✓</li><li>POS Order, On Credit Order (Prepay Order if <i>Generate Invoice</i>): also creates the invoice ✓</li><li>Standard Order: reserves the ordered quantity; shipment and invoice are made next ✓</li><li>Quotation: reserves the quantity and creates nothing else</li><li>Proposal: reserves nothing and creates nothing else</li><li>Prepay Order: waits for a payment (status Waiting Payment)</li><li>The next action offered is Close</li></ul><p><b>When it refuses</b>, legacy says: “Period Closed” ✓; “Product is not on Price List” ✓; “Business Partner with this Order over Credit Hold” ✓; “Fill mandatory fields: Shipper”; “No Document Lines found”; “Product … Exclude Auto Delivery”; “Line No … - Invalid: Date Promised”; “Cannot change Document Type”; “Cannot reserve Stock”; “Error calculating tax”; “Error in payment schedule”.</p><p><i>Read from iDempiere''s MOrder.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p><p><strong>1 · Sales Order</strong></p><p><a href=\"https://red1oon.github.io/BIMCompiler/ERPUserGuide/#1-sales-order\" target=\"_blank\">1 · Sales Order …</a></p>', '2026-11-23 06:25:54', 100)",
