"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000001, 'f02888ee-9284-5d0e-ba81-9b2ac95b1d73', 0, '2026-11-23 06:25:54', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment', 'Y', 'Shipment (Customer) + 2 · Shipment', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000001, 1000001, 'acd8379a-62f4-576a-8360-00e12acc2d7d', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Shipment (Customer)</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"123\">Business Partner</a>, Partner Location (<a href=\"#\" data-help-win=\"123\">Business Partner</a>).</p><p><b>Do it.</b> Fill <b>Shipment</b>, then <b>Shipment Line</b>, <b>Packages</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Pick/QA Confirmation: Yes: creates a pick/QA confirmation document with one line per shipment line</li><li>Ship/Receipt Confirmation: Yes: creates a ship/receipt confirmation (after the pick/QA one when both are on)</li><li>Stays In Progress while a non-customer confirmation is unprocessed</li><li>Movement Type Customer Shipment, Vendor Returns: takes the line quantity out of the locator''s on-hand stock (stocked products)</li><li>Movement Type Customer Returns, Vendor Receipts: adds the line quantity to the locator''s on-hand stock (stocked products)</li><li>Reduces the product''s reserved stock for the order line''s warehouse ✓</li><li>Raises order line delivered qty on shipment (C-), lowers it on customer return (C+) ✓</li><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “Either Order or RMA can be process on this document.”; “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Attribute Set Mandatory (Line No #… , Product=… )”; “Open: Ship/Receipt Confirmation”; “Insufficient Stock Coverage. A shipment should not be allowed if there is insufficient stock before the shipment’s movement date.”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; and 9 more in MInOut.java.</p><p><i>Read from iDempiere''s MInOut.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p><p><strong>2 · Shipment</strong></p><p><a href=\"https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment\" target=\"_blank\">2 · Shipment …</a></p>', '2026-11-23 06:25:54', 100)",
