"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000040, '430ffb65-f407-57a7-9a07-4195b5b7fc3c', 0, '2026-11-23 06:25:54', 100, 'T', NULL, 'Y', 'Inventory Decrease/Increase', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000040, 1000040, '840dbbcf-f761-5224-94d0-b6aff66943a1', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Inventory Decrease/Increase</strong></p><p><b>Before you start.</b> These must exist first: Warehouse (<a href=\"#\" data-help-win=\"139\">Warehouse and Locators</a>), <a href=\"#\" data-help-win=\"135\">Document Type</a>.</p><p><b>Do it.</b> Fill <b>Internal Use</b>, then <b>Internal Use Line</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “No Document Lines found”; “Line No … : Fill mandatory fields: Attribute Set Instance”; “Document inventory subtype not configured, cannot complete”; “Current Cost for Line … have changed.”; “Storage on hand not updated for DateLastInventory”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory (MA) - …”; “Transaction not inserted(2)”; “Cannot correct Inventory OnHand (MA) - …”.</p><p><i>Read from iDempiere''s MInventory.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '2026-11-23 06:25:54', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000040 WHERE ad_tab_id=682 AND ad_ctxhelp_id IS NULL",
