"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000046, 1000046, '957b6f0f-a158-5a00-8bfc-011ef2478d42', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Product Costs</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"144\">Product Category</a>, UOM (<a href=\"#\" data-help-win=\"120\">Unit of Measure</a>).</p><p><b>Do it.</b> Fill <b>Select Product</b>, then <b>Product Costs</b>, <b>Cost Details</b>, <b>Cost Queue</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000046 WHERE ad_tab_id=700 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000047, '29a93109-2ed5-5d57-86b6-de38e6d7a1ed', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Reporting Hierarchy', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000047, 1000047, '50c98dfd-4d90-539e-9425-a1338fd6aa72', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Reporting Hierarchy</strong></p><p><b>Before you start.</b> These must exist first: Organization Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Account Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Activity Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), BPartner Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Product Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Project Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Campaign Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>), Sales Region Tree (<a href=\"#\" data-help-win=\"163\">Tree</a>).</p><p><b>Do it.</b> Fill <b>Reporting Hierarchy</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000047 WHERE ad_tab_id=766 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000048, 'd20f7b02-fc32-5c5c-8075-9c408b56ca92', 0, '2026-11-23 06:25:54', 100, 'T', NULL, 'Y', 'Requisition', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000048, 1000048, '245629e9-aa5d-510c-bf66-501fe55b9655', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Requisition</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"135\">Document Type</a>, User/Contact (<a href=\"#\" data-help-win=\"108\">User</a>), Warehouse (<a href=\"#\" data-help-win=\"139\">Warehouse and Locators</a>), <a href=\"#\" data-help-win=\"146\">Price List</a>.</p><p><b>Do it.</b> Fill <b>Requisition</b>, then <b>Requisition Line</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Sets TotalLines to the sum of line net amounts when it differs ✓</li><li>Overwrite Date on Complete: Yes: sets document date to today and tests its period</li><li>Overwrite Sequence on Complete: Yes: assigns a new document number from the sequence</li><li>Offers Close as the next Document Action</li></ul><p><i>Read from iDempiere''s MRequisition.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '2026-11-23 06:25:54', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000048 WHERE ad_tab_id=641 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000049, '968fcc93-483d-5e36-858b-ab67c2d4a929', 0, '2026-11-23 06:25:54', 100, 'T', NULL, 'Y', 'Invoice Payment Schedule', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000049, 1000049, 'b65ff297-bbc4-5834-ab5d-61852d702c29', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Invoice Payment Schedule</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"141\">Payment Term</a>.</p><p><b>Do it.</b> Fill <b>Invoice</b>, then <b>Payment Schedule</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Payment Rule On Credit, Direct Debit: creates the invoice payment schedule</li><li>Payment Rule Cash: creates and completes a cash payment for the invoice total</li><li>Adds the invoiced quantity to the sales order line ✓</li><li>Prepay Order: allocates completed unallocated prepayments of the order to the invoice</li><li>Adds invoice total to partner open balance (cash rule non-POS excepted) ✓</li><li>Adds invoice total to partner credit used ✓</li><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “No Document Lines found”; “No Document Type”; “Error calculating Tax”; “Error in payment schedule”; “No account defined for this organization / currency”; “No document type”; “Cannot Complete the Payment : [… ] …”; “Could not update Order Line”; “Could not create PO Matching”; “Could not update RMA Line”; “Could not update Business Partner User”; “InvoicedAmt: … &lt;&gt; AuthorizedAmt: …”.</p><p><i>Read from iDempiere''s MInvoice.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '2026-11-23 06:25:54', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000049 WHERE ad_tab_id=501 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000050, '5afc2cd5-b569-5ab3-b51e-819b756d7ac8', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Accounting Dimensions', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000050, 1000050, '92553be0-b009-5bde-9ebb-4d3bdfdb8d61', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Accounting Dimensions</strong></p><p><b>Needed by.</b> Each of these asks for one on its header: <a href=\"#\" data-help-win=\"200105\">Bank/Cash Transfer</a>.</p><p><b>Do it.</b> Fill <b>Organization Dimension</b>, then <b>Sales Region Dimension</b>, <b>Activity Dimension</b>, <b>Project Dimension</b>, <b>Business Partner Dimension</b>, <b>Product Dimension</b>, <b>Campaign Dimension</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
