"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000052, 1000052, '1c2e8990-145c-5824-a1d1-d042baaff06a', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Commission</strong></p><p><b>Before you start.</b> These must exist first: Business Partner / Sales Rep (<a href=\"#\" data-help-win=\"123\">Business Partner</a>), <a href=\"#\" data-help-win=\"115\">Currency</a>.</p><p><b>Do it.</b> Fill <b>Commission</b>, then <b>Commission Line</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
