"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000058, '9463f64e-0e9d-5627-93c9-556e592ce357', 0, '2026-11-23 06:25:54', 100, 'T', NULL, 'Y', 'Inventory Move', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000058, 1000058, '74a84bad-6ca8-5892-a761-a2fa6d9c9248', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Inventory Move</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"135\">Document Type</a>.</p><p><b>Do it.</b> Fill <b>Move</b>, then <b>Move Line</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>In Transit: Yes: creates a movement confirmation (if none exists) for an in-transit document type</li><li>Stays In Progress while a movement confirmation is unprocessed</li><li>Takes the line quantity out of the source locator''s on-hand stock (stocked products)</li><li>Adds the line quantity to the destination locator''s on-hand stock (stocked products)</li><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Line No … : Fill mandatory fields: Attribute Set Instance”; “Line No … : Fill mandatory fields: Attribute Set Instance To”; “Open: Move Confirm”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; “Transaction From not inserted (MA) [… ] -”; “Transaction To not inserted (MA) [… ] -”; “Transaction To not inserted [… ] -”.</p><p><i>Read from iDempiere''s MMovement.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '2026-11-23 06:25:54', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000058 WHERE ad_tab_id=259 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000059, '49d07a5b-87e7-592b-8e1e-5cf11623e10e', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Commission Run', '2026-11-16 19:33:33', 100)",
