"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000082, '8f56e245-e63f-5ae5-8afc-fba9c9adfd0e', 0, '2026-11-23 06:25:54', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match', 'Y', 'Material Receipt + 6 · Purchase Order → Receipt → Vendor Invoice → Match', '2026-11-23 06:25:54', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000082, 1000082, '7a81b6c1-a21a-57d4-bbc2-c88bf8759119', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Material Receipt</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"123\">Business Partner</a>, Partner Location (<a href=\"#\" data-help-win=\"123\">Business Partner</a>).</p><p><b>Do it.</b> Fill <b>Material Receipt</b>, then <b>Receipt Line</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Ship/Receipt Confirmation: Yes: creates a ship/receipt confirmation (after the pick/QA one when both are on)</li><li>Stays In Progress while a non-customer confirmation is unprocessed</li><li>Movement Type Customer Shipment, Vendor Returns: takes the line quantity out of the locator''s on-hand stock (stocked products)</li><li>Movement Type Customer Returns, Vendor Receipts: adds the line quantity to the locator''s on-hand stock (stocked products)</li><li>Reduces the product''s ordered stock for the order line''s warehouse</li><li>Creates an invoice-receipt match when the receipt line has an invoice line</li><li>Creates a PO match linking the receipt line to its order line ✓</li><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “Either Order or RMA can be process on this document.”; “Period Closed”; “Back-Date transaction not allowed”; “No Document Lines found”; “Attribute Set Mandatory (Line No #… , Product=… )”; “Open: Ship/Receipt Confirmation”; “Insufficient Stock Coverage. A shipment should not be allowed if there is insufficient stock before the shipment’s movement date.”; “More than line qty on attribute tab for line …”; “Cannot correct Inventory OnHand (MA) [… ] - …”; “Could not create Material Transaction (MA) [… ]”; and 8 more in MInOut.java.</p><p><i>Read from iDempiere''s MInOut.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p><p><a href=\"https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match\" target=\"_blank\">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', '2026-11-23 06:25:54', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000082 WHERE ad_tab_id=296 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000083, '43f34d6b-cd20-5141-bf6b-d40826a19bc3', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Payment Selection', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000083, 1000083, '2ea9e5a7-8d5f-579e-8682-079e3f541e2f', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Payment Selection</strong></p><p><b>Before you start.</b> These must exist first: Bank Account (<a href=\"#\" data-help-win=\"158\">Bank/Cash</a>).</p><p><b>Do it.</b> Fill <b>Payment Selection</b>, then <b>Payment Selection Line</b>, <b>Prepared Payment</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
