"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000084, 'd9289f99-342c-5496-82ad-7bbf46981cc2', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Performance Measure', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000084, 1000084, '5466ceeb-9446-5b78-82be-3458b0d94f62', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Performance Measure</strong></p><p><b>Do it.</b> Fill <b>Measure</b>, then <b>Achievement</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
