"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000085, '7b66fbb5-9b87-52d2-8377-a9332a9f9a00', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Accounting Fact Balances', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000085, 1000085, '9b269e01-72d0-57df-b6bd-9a8b3eaf0943', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Accounting Fact Balances</strong></p><p><b>Do it.</b> Fill <b>Daily Balances</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
