"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000086, '270c8a72-4d20-593a-afc4-de2be14ea11f', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match', 'Y', 'Matched Invoices + 6 · Purchase Order → Receipt → Vendor Invoice → Match', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000086, 1000086, '9aea9fcc-d656-592a-9a0f-20e6d78231ef', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Matched Invoices</strong></p><p><b>Do it.</b> Fill <b>Match Invoice</b>.</p><p><i>Read from the dictionary.</i></p><p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p><p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <a href=\"#\" data-help-win=\"181\">Purchase Order</a>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p><ul><li><b><a href=\"#\" data-help-win=\"181\">Purchase Order</a></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><a href=\"#\" data-help-win=\"184\">M_InOut</a></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><a href=\"#\" data-help-win=\"107\">M_MatchInv</a></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><a href=\"#\" data-help-win=\"228\">M_MatchPO</a></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000086 WHERE ad_tab_id=408 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000087, '960c5a74-c7d4-5964-a511-b1b55a7a3db0', 0, '2026-11-16 19:33:33', 100, 'T', NULL, 'Y', 'Business Partner Info', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000087, 1000087, '7f289333-723e-5cbc-921a-05a03cef01fc', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Business Partner Info</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"192\">Business Partner Group</a>.</p><p><b>Needed by.</b> Each of these asks for one on its header: <a href=\"#\" data-help-win=\"143\">Sales Order</a>, <a href=\"#\" data-help-win=\"181\">Purchase Order</a>, <a href=\"#\" data-help-win=\"169\">Shipment (Customer)</a>, <a href=\"#\" data-help-win=\"195\">Payment and Receipt</a>, <a href=\"#\" data-help-win=\"183\">Purchase Invoice and Credit/Debit Note</a>, <a href=\"#\" data-help-win=\"184\">Material Receipt</a>, <a href=\"#\" data-help-win=\"167\">Sales Invoice and Credit/Debit Note</a>, <a href=\"#\" data-help-win=\"200105\">Bank/Cash Transfer</a>.</p><p><b>Do it.</b> Fill <b>Partner Selection</b>, then <b>Partner Orders</b>, <b>Partner Shipments</b>, <b>Partner Invoices</b>, <b>Partner Payments</b>, <b>Partner Assets</b>, <b>Partner Requests</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
