"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000104, 1000104, '6ac1eac9-d78b-5437-91b8-199c70b07a33', 0, '2026-11-23 06:25:54', 100, 'Y', NULL, '<p><strong>Payments into Batch</strong></p><p><b>Before you start.</b> These must exist first: Bank Account (<a href=\"#\" data-help-win=\"158\">Bank/Cash</a>), <a href=\"#\" data-help-win=\"135\">Document Type</a>, <a href=\"#\" data-help-win=\"115\">Currency</a>.</p><p><b>Do it.</b> Fill <b>Batch</b>, then <b>Lines</b>; then the Document Action <b>Complete</b>.</p><p><b>What Complete does.</b></p><ul><li>Recalculates the deposit amount from the active lines</li><li>Offers Close as the next document action</li></ul><p><b>When it refuses</b>, legacy says: “No Document Lines found”.</p><p><i>Read from iDempiere''s MDepositBatch.java and the dictionary. ✓ = seen in a legacy run of 2026-11-23.</i></p>', '2026-11-23 06:25:54', 100)",
