"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000105, 1000105, '2735fa6e-3f05-5eb8-ac88-1edf628fefe4', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>Alert</strong></p><p><b>Before you start.</b> These must exist first: <a href=\"#\" data-help-win=\"312\">Alert Processor</a>.</p><p><b>Do it.</b> Fill <b>Alert</b>, then <b>Alert Rule</b>, <b>Alert Recipient</b>.</p><p><i>Read from the dictionary.</i></p>', '2026-11-16 19:33:33', 100)",
